<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class PortalContext {public function handle(Request $r,Closure $next){Auth::shouldUse(config('portal.kind')==='owner'?'owner':'web');$u=$r->user();if($u instanceof \App\Models\Owner&&!$u->activated){Auth::guard()->logout();$r->session()->invalidate();return response()->json(['message'=>'Tu acceso de propietario está desactivado.'],401);}if($u&&$u->password_reset_at&&$r->session()->get('auth_password_version')!==$u->password_reset_at){Auth::guard()->logout();$r->session()->invalidate();$r->session()->regenerateToken();if($r->is('api/*'))return response()->json(['message'=>'Tu contraseña cambió. Inicia sesión nuevamente.','csrf'=>csrf_token()],401);}if($u instanceof \App\Models\Owner&&!$u->email_verified_at&&!in_array($r->method(),['GET','HEAD','OPTIONS'])&&!$r->is('api/email/*','api/owner-auth/*','api/password/*','api/realtime/*'))return response()->json(['message'=>'Verifica tu correo antes de modificar tu negocio.','code'=>'email_verification_required'],403);return $next($r);}}
